pragma solidity >=0.8.0;
contract EventOrderPackM1 {
    event Mark(uint8 indexed tag, string indexed s, bytes b);
    uint8 public flag;
    string public s1;
    bytes public b1;
    function mix() external {
        flag = 1;
        s1 = "a";
        b1 = hex"01";
        emit Mark(1, s1, b1);
        b1 = hex"02";
        emit Mark(1, s1, b1);
    }
    function getAll() external view returns (uint8, string memory, bytes memory) {
        return (flag, s1, b1);
    }
}
